const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'F' },
      { kind: 'text', payload: '瓶内气压与摩擦的合力' },
      { kind: 'text', payload: '木塞' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var cx = W * 0.50;
    var neckLeft = W * 0.38;
    var neckRight = W * 0.62;
    var neckTop = H * 0.26;
    var neckBottom = H * 0.88;
    var wall = Math.max(2, W * 0.008);
    var corkLeft = W * 0.415;
    var corkRight = W * 0.585;
    var corkTop = H * 0.20;
    var corkBottom = H * 0.34;

    var leftWallCmds = [
      ['M', neckLeft, neckTop],
      ['L', neckLeft + wall, neckTop],
      ['L', neckLeft + wall, neckBottom],
      ['L', neckLeft, neckBottom],
      ['Z']
    ];
    var rightWallCmds = [
      ['M', neckRight - wall, neckTop],
      ['L', neckRight, neckTop],
      ['L', neckRight, neckBottom],
      ['L', neckRight - wall, neckBottom],
      ['Z']
    ];
    var bottomCmds = [
      ['M', neckLeft, neckBottom - wall],
      ['L', neckRight, neckBottom - wall],
      ['L', neckRight, neckBottom],
      ['L', neckLeft, neckBottom],
      ['Z']
    ];
    var corkBackCmds = [
      ['M', corkLeft - 2, corkTop - 2],
      ['L', corkRight + 2, corkTop - 2],
      ['L', corkRight + 2, corkBottom + 2],
      ['L', corkLeft - 2, corkBottom + 2],
      ['Z']
    ];
    var corkCmds = [
      ['M', corkLeft, corkTop],
      ['L', corkRight, corkTop],
      ['L', corkRight, corkBottom],
      ['L', corkLeft, corkBottom],
      ['Z']
    ];
    var upArrowCmds = visualSdk.arrow(cx, corkTop - H * 0.02, cx, H * 0.06);
    var downArrowCmds = visualSdk.arrow(cx, corkBottom + H * 0.02, cx, H * 0.53);

    return {
      schemaVersion: 1,
      sceneId: 'cork-force',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'leftWall', commands: leftWallCmds },
        { id: 'rightWall', commands: rightWallCmds },
        { id: 'neckBottom', commands: bottomCmds },
        { id: 'corkBack', commands: corkBackCmds },
        { id: 'cork', commands: corkCmds },
        { id: 'upArrow', commands: upArrowCmds },
        { id: 'downArrow', commands: downArrowCmds }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'leftWall', fill: '#26354a' },
          { type: 'path', pathId: 'rightWall', fill: '#26354a' },
          { type: 'path', pathId: 'neckBottom', fill: '#26354a' },
          { type: 'path', pathId: 'corkBack', fill: '#6B3E26' },
          { type: 'path', pathId: 'cork', fill: '#B97A4A' },
          { type: 'path', pathId: 'upArrow', fill: '#C0392B' },
          { type: 'path', pathId: 'downArrow', fill: '#2C6E9B' },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: cx + W * 0.035, y: (corkTop - H * 0.02 + H * 0.06) / 2 }, hAlign: 'left', vAlign: 'middle', color: '#C0392B' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: cx + W * 0.035, y: H * 0.45 }, hAlign: 'left', vAlign: 'middle', color: '#2C6E9B' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: corkRight + W * 0.025, y: (corkTop + corkBottom) / 2 }, hAlign: 'left', vAlign: 'middle', color: '#6B3E26' }
        ]
      }
    };
  }
};
